ssize_t ssl_sendmsg ( conn * c , struct msghdr * msg , int flags ) { assert ( c != NULL ) ; size_t buf_remain = settings . ssl_wbuf_size ; int bytes = 0 ; size_t to_copy ; int i ; assert ( c -> ssl_wbuf ) ; assert ( pthread_equal ( c -> thread -> thread_id , pthread_self ( ) ) != 0 ) ; char * bp = c -> ssl_wbuf ; for ( i = 0 ; i < msg -> msg_iovlen ; i ++ ) { size_t len = msg -> msg_iov [ i ] . iov_len ; to_copy = len < buf_remain ?len : buf_remain ; memcpy ( bp + bytes , ( void * ) msg -> msg_iov [ i ] . iov_base , to_copy ) ; buf_remain -= to_copy ; bytes += to_copy ; if ( buf_remain == 0 ) { break ; } } return SSL_write ( c -> ssl , c -> ssl_wbuf , bytes ) ; } 